const ROW = { top:"qwertyuiop", home:"asdfghjkl", bottom:"zxcvbnm" };
const LEFT  = "qwertasdfgzxcvb";
const RIGHT = "yuiophjklnm";
const ALL_LETTERS = "abcdefghijklmnopqrstuvwxyz";
const pick = a => a[Math.floor(Math.random()*a.length)];

const STAGES = {
  "home-both":  { charset: ROW.home },
  "home-left":  { charset: "asdfg" },
  "home-right": { charset: "hjkl" },
  "top-both":   { charset: ROW.top },
  "top-left":   { charset: "qwert" },
  "top-right":  { charset: "yuiop" },
  "bottom-both":  { charset: ROW.bottom },
  "bottom-left":  { charset: "zxcvb" },
  "bottom-right": { charset: "nm" },
  "all-both":  { charset: ALL_LETTERS },
  "all-left":  { charset: LEFT },
  "all-right": { charset: RIGHT },
  "symbols-both":  { charset: ALL_LETTERS + ",.'!?;:\"()-", symbols: ",.'!?;:\"()-" },
  "symbols-left":  { charset: ALL_LETTERS + "!()", symbols: "!()" },
  "symbols-right": { charset: ALL_LETTERS + ",.'?;:", symbols: ",.'?;:" },
  "caseMix-both":  { charset: ALL_LETTERS },
  "caseMix-left":  { charset: RIGHT },   // 右手打字＋左手 Shift
  "caseMix-right": { charset: LEFT },    // 左手打字＋右手 Shift
  "caseSymbolMix-both": { charset: ALL_LETTERS + ",.'!?;:\"()-", symbols: ",.'!?;:\"()-" },
  "sentence": { charset: ALL_LETTERS }
};
export const TOWER_DEFENSE_STAGE_ORDER = Object.keys(STAGES);

export function getStageDefinition(key){
  const d = STAGES[key];
  return d ? Object.assign({ key }, d) : null;
}

function fits(word, charset){
  for(const ch of word.toLowerCase()) if(charset.indexOf(ch) === -1) return false;
  return true;
}
const _cache = {};
function wordsFor(key){
  if(_cache[key]) return _cache[key];
  const d = STAGES[key];
  const letters = d ? d.charset.replace(/[^a-z]/g, "") : ALL_LETTERS;
  const list = VOCAB.filter(w => fits(w, letters));
  // 符合按鍵的真字太少（< 8 個）時不硬湊，交給 randomSequence 用這些按鍵隨機組字
  return (_cache[key] = list.length >= 8 ? list : []);
}

// 用這個關卡的按鍵隨機組出 min~max 個字元
export function randomSequence(key, min = 2, max = 5){
  const d = STAGES[key] || STAGES["all-both"];
  const chars = d.charset;
  const len = min + Math.floor(Math.random()*(max-min+1));
  let s = "";
  for(let i=0;i<len;i++) s += chars[Math.floor(Math.random()*chars.length)];
  return s;
}

function capitalize(w){ return w.charAt(0).toUpperCase() + w.slice(1); }

export function randomVocabWord(key){
  const d = STAGES[key] || STAGES["all-both"];
  if(key.indexOf("symbols-") === 0 || key.indexOf("caseSymbolMix") === 0){
    const toks = SYMBOL_TOKENS.filter(t => fits(t, d.charset));
    if(toks.length && Math.random() < 0.6) return pick(toks);
    const w = pick(wordsFor(key.indexOf("caseSymbolMix")===0 ? "all-both" : "all-both").filter(x=>x.length<=7));
    const sy = d.symbols;
    const p = sy[Math.floor(Math.random()*sy.length)];
    if(p === "'") return w + "'s";
    if(p === "-") return w + "-" + pick(wordsFor("all-both").filter(x=>x.length<=5));
    return w + p;
  }
  if(key.indexOf("caseMix") === 0){
    const pool = wordsFor(key);
    if(pool.length === 0) return randomSequence(key, 3, 6);
    if(key === "caseMix-both" && Math.random() < 0.4){
      const pn = PROPER_NOUNS; if(pn.length) return pick(pn);
    }
    const w = pick(pool);
    return Math.random() < 0.25 ? w.toUpperCase() : capitalize(w);
  }
  if(key === "sentence") return randomSentence();
  const pool = wordsFor(key);
  if(pool.length === 0) return randomSequence(key, 2, 5);
  return pick(pool);
}

export function randomSentence(){
  return pick(SENTENCES);
}
